function CardProgressionEquipmentComparedNode:Awake()
    self.__EventOperateEquipOrCore = Events.AddListener(Constants.EventNames.UICultivateEquipOperateEquipOrCore, Bind(self, self.OnEventOperateEquipOrCore))
