function CardProgressionEquipmentComparedNode:Start()
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = Bind(self, self.Update)
        self._behaviourAction = behaviourAction
    end
end

function CardProgressionEquipmentComparedNode:Update()
    if Utils.TouchCount() > 0 and (not self.__closing) and not GuideUtils.IsInGuiding() then
        local positionV = Utils.GetInputDownPos()
        local position = Vector2.New(positionV.x, positionV.y)
        if position ~= Vector2.zero then
            local camera = UIModule.RootCanvas.canvas.worldCamera
            local isInRect = RectTransformUtility.RectangleContainsScreenPoint(self.CurEquipIntroductionNode, position, camera)
            local isInScoreRect = RectTransformUtility.RectangleContainsScreenPoint(self.CurEvaluateScoreDetail, position, camera)
            local isActive = KTool.IsActive(self.CompareIntroductionNode.gameObject)
            local isInRect1 = isActive and RectTransformUtility.RectangleContainsScreenPoint(self.CompareIntroductionNode, position, camera)
            local isInScoreRect1 = isActive and RectTransformUtility.RectangleContainsScreenPoint(self.CompareEvaluateScoreDetail, position, camera)
            if not (isInRect or isInScoreRect or isInRect1 or isInScoreRect1) then
                --Events.Broadcast(Constants.EventNames.UICultivateEquipCompareViewClose)
                self:HideView()
            end
        end
    end
end

function CardProgressionEquipmentComparedNode:OnDestroy()
