    Events.RemoveListener(Constants.EventNames.UICultivateEquipOperateEquipOrCore, self.__EventOperateEquipOrCore)
    Events.RemoveListener(Constants.EventNames.CardProgressEquipInfoSwitchScorePanelState, self.__EventSwitchScorePanel)
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end
