--region init
function CardProgressionEquipmentComparedNode:InitParams(equipDojoList, curDojo, compareDojo, equipType, part)
    local isExistsCompareDojo = compareDojo ~= nil
    local isCompare = curDojo ~= nil and isExistsCompareDojo
    local isCore = equipType == EquipType.Core
    local curParams, compareParams
    if isCompare then
        curParams = {
            part = part,
            dojo = curDojo,
            status = Status.Installed,
            equipDojoList = isCore and equipDojoList or nil,
        }
        
        local compareStatus
        if checkNumber(compareDojo.playerCardId) == 0 then
            compareStatus = isCore and Status.Replace or Status.CultivateAndReplace
        else
            compareStatus = Status.Installed
        end

        compareParams = {
            part = part,
            dojo = compareDojo,
            equipDojoList = isCore and equipDojoList or nil,
            status =  isCore and Status.Replace or Status.CultivateAndReplace,
            iShowCanActive = true,
            mainAttrDif = checkInt(compareDojo.mainAttrNum) - checkInt(curDojo.mainAttrNum)
        }

    elseif isExistsCompareDojo then
        curParams = {
            part = part,
            dojo = compareDojo,
            equipDojoList = isCore and equipDojoList or nil,
            status = isCore and Status.Install or Status.CultivateAndInstall,
            iShowCanActive = true,
        }
    else
        curParams = {
            part = part,
            dojo = curDojo,
            status = isCore and Status.Uninstall or Status.CultivateAndUninstall,
            equipDojoList = isCore and equipDojoList or nil,

        }
    end
    return curParams, compareParams
end

function CardProgressionEquipmentComparedNode:InitEquipCultivateParams(curDojo, compareDojo, part)
    local isExistsCompareDojo = compareDojo ~= nil
    local curParams, compareParams
    curParams = {
        part = part,
        dojo = curDojo,
        status = Status.HideButton,
    }
    if isExistsCompareDojo then
        compareParams = {
            part = part,
            dojo = compareDojo,
            status = Status.HideButton,
        }
    end
    return curParams, compareParams
end
--endregion init

--region handler
function CardProgressionEquipmentComparedNode:OnEventOperateEquipOrCore(params, equipType, direction)

    local toastText, cueName
    local status = params.status
    local isRight = direction == 2
    if isRight then
        local realStatus2ToastText = {
            [Status.Install]   = localize("安装成功"),
            [Status.Uninstall] = localize("卸下成功"),
            [Status.Replace]   = localize("替换成功"),
        }
        local status2RealStatus = {
            [Status.CultivateAndInstall] = Status.Install,
            [Status.CultivateAndUninstall] = Status.Uninstall,
            [Status.CultivateAndReplace] = Status.Replace,
        }

        local realStatus = status2RealStatus[status] or status
        toastText = realStatus2ToastText[realStatus]

        local realStatus2CueName = {
            [Status.Install]   = UISheets.UI_Menu.ui_anzhuang,
            [Status.Replace]   = UISheets.UI_Menu.ui_anzhuang,
        }
        cueName = realStatus2CueName[realStatus]
    end

    if toastText then
        --GameUtils.Toast(toastText)
    end

    if cueName then
        CriWareUtils.PlaySe(UISheets.UI_Menu.path, cueName)
    end

    self:HideView()
end

function CardProgressionEquipmentComparedNode:OnEventSwitchScorePanel(isShow)
    self._isShowScorePanel = isShow 
    if isShow then
        CfUtils.PlayAnimation(self.Root, 'CultivateOverseaEquipDetailsGroup_LeftOut', true)
    else
        CfUtils.PlayAnimation(self.Root, 'CultivateOverseaEquipDetailsGroup_LeftBack', true)
    end
end
--endregion handler

--region public
function CardProgressionEquipmentComparedNode:RefreshUI(equipIdList, curDojo, compareDojo, equipType, part, playerCardId)
    local equipDojoList = {}
    for i = 1, Constants.CardEquipmentNo do
        local id = checkNumber(equipIdList[i])
        if id > 0 then
            equipDojoList[i] = equipComp:GetEquipById(id)
        end
    end

    self:RefreshUIByEquipDojoList(equipDojoList, curDojo, compareDojo, equipType, part, playerCardId)
end

function CardProgressionEquipmentComparedNode:RefreshEquipCultivateUI(curDojo, compareDojo, equipType, part)
    local curParams, compareParams = self:InitEquipCultivateParams(curDojo, compareDojo, part)
    KTool.SetActive(self.Container.gameObject, true)
    --KTool.SetActive(self.Shadow.gameObject, compareParams ~= nil)
    KTool.SetActive(self.CompareIntroductionNode.gameObject, compareParams ~= nil)
    self:RefreshEquipIntroductionNode(self.CurEquipIntroductionNode, curParams, equipType, nil, false)
    if compareParams ~= nil then
        self:RefreshEquipIntroductionNode(self.CompareIntroductionNode,  compareParams, equipType, nil, true)
    end
end

function CardProgressionEquipmentComparedNode:RefreshPresetUI(equipIdList, curDojo, compareDojo, equipType, part)
    local equipDojoList = {}
    for i = 1, Constants.CardEquipmentNo do
        local id = checkNumber(equipIdList[i])
        if id > 0 then
            equipDojoList[i] = equipComp:GetEquipById(id)
        end
    end

    self:RefreshPresetUIByEquipDojoList(equipDojoList, curDojo, compareDojo, equipType, part)
end
